            put( "info", Myriad.this.extend(new HashMap<String, Object>() {{
                put( "transactionHash", txHash );
            }}, Myriad.this.safeDict(quote, "info", new HashMap<String, Object>() {{}})) );
            put( "outcome", Myriad.this.safeString(market, "outcome") );
